using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        const string A = "Assets/Art/InvestigationV36/R103/";
        static Material[] Mats(Renderer rr)
        {
            return rr.sharedMaterials.Select(m =>
            {
                if (!m)
                    return null;
                string p = A + "Materials/" + m.name + ".mat";
                var material = AssetDatabase.LoadAssetAtPath<Material>(p);
                if (!material)
                {
                    material = new Material(Shader.Find("Universal Render Pipeline/Lit"));
                    material.name = m.name;
                    material.color = m.HasProperty("_BaseColor") ? m.GetColor("_BaseColor") : m.color;
                    material.SetFloat("_Smoothness", .12f);
                    AssetDatabase.CreateAsset(material, p);
                }

                return material;
            }).ToArray();
        }

        static GameObject Part(string file, string mesh, string name, Transform parent, Vector3 pos)
        {
            var source = AssetDatabase.LoadAssetAtPath<GameObject>(A + file + ".fbx").GetComponentsInChildren<MeshFilter>().Single(f => f.name == mesh);
            var g = new GameObject(name);
            g.transform.SetParent(parent, false);
            g.transform.localPosition = pos;
            g.AddComponent<MeshFilter>().sharedMesh = source.sharedMesh;
            g.AddComponent<MeshRenderer>().sharedMaterials = Mats(source.GetComponent<Renderer>());
            return g;
        }

        static void Assign(GameObject target, string mesh)
        {
            var source = AssetDatabase.LoadAssetAtPath<GameObject>(A + "EVIDENCE.fbx").GetComponentsInChildren<MeshFilter>().Single(f => f.name == mesh);
            target.GetComponent<MeshFilter>().sharedMesh = source.sharedMesh;
            target.GetComponent<Renderer>().sharedMaterials = Mats(source.GetComponent<Renderer>());
            var cc = target.GetComponent<BoxCollider>();
            if (cc)
            {
                cc.center = source.sharedMesh.bounds.center;
                cc.size = source.sharedMesh.bounds.size + new Vector3(.005f, .02f, .005f);
            }
        }

        static void Layer(Transform t, int n)
        {
            foreach (var child in t.GetComponentsInChildren<Transform>(true))
                child.gameObject.layer = n;
        }

        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying || EditorApplication.isCompiling)
                throw new Exception("Edit compiled required");
            var scene = EditorSceneManager.GetActiveScene();
            if (!scene.path.EndsWith("r103.unity"))
                throw new Exception(scene.path);
            AssetDatabase.Refresh();
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!s)
                throw new Exception("R103 session absent");
            foreach (string file in new[]{"EVIDENCE", "RepairEventActor"})
            {
                var imp = (ModelImporter)AssetImporter.GetAtPath(A + file + ".fbx");
                imp.isReadable = true;
                imp.globalScale = 1;
                imp.importAnimation = file == "RepairEventActor";
                if (file == "RepairEventActor")
                    imp.animationType = ModelImporterAnimationType.Legacy;
                imp.SaveAndReimport();
            }

            var workshop = s.transform.Find("Workshop_GDD36");
            foreach (var pair in new[]{new[]{"slide", "SlideMarks"}, new[]{"shoeprint", "ShoePrint"}, new[]{"shoe", "ShoeSample"}, new[]{"coat", "CoatSample"}, new[]{"fabric", "TornFabric"}})
                Assign(workshop.Find("Evidence_" + pair[0]).gameObject, pair[1]);
            workshop.Find("Evidence_shoeprint").localPosition = workshop.Find("Evidence_slide").localPosition;
            var preview = Part("EVIDENCE", "TraceCrossing", "Trace_crossing_inspection", null, Vector3.zero);
            var prefab = PrefabUtility.SaveAsPrefabAsset(preview, A + "TraceCrossing.prefab");
            Object.DestroyImmediate(preview);
            foreach (string id in new[]{"slide", "shoeprint"})
                workshop.Find("Evidence_" + id).GetComponent<InvestigationInteractable>().inspectionPrefab = prefab;
            var control = workshop.Find("Evidence_shoecontrol");
            if (!control)
            {
                var g = Part("EVIDENCE", "ShoeControl", "Evidence_shoecontrol", workshop, new Vector3(-2.25f, .94f, .3f));
                g.AddComponent<BoxCollider>();
                var i = g.AddComponent<InvestigationInteractable>();
                i.evidenceId = "shoecontrol";
                i.verb = "Xem";
                Assign(g, "ShoeControl");
            }

            foreach (var actor in s.GetComponentsInChildren<InvestigationActor>(true).Where(a => a.puppet).ToArray())
            {
                string tag = actor.name.StartsWith("R12") ? "Label_R12" : "Label_R03";
                if (!actor.transform.Find("Readable_asset_tag"))
                    Part("EVIDENCE", tag, "Readable_asset_tag", actor.transform, Vector3.zero);
            }

            // Actual event actor comes from the continuous Blender animation; no second pose owner.
            var old = s.transform.Find("Repair_clip_illustration/EventActor_R103");
            if (old)
                Object.DestroyImmediate(old.gameObject);
            var clipRoot = s.clipGate.transform.parent;
            var eventActor = (GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(A + "RepairEventActor.fbx"));
            eventActor.name = "EventActor_R103";
            eventActor.transform.SetParent(clipRoot, false);
            foreach (var ani in eventActor.GetComponentsInChildren<Animation>())
                ani.enabled = false;
            foreach (var render in eventActor.GetComponentsInChildren<Renderer>())
                render.sharedMaterials = Mats(render);
            if (s.clipTu && s.clipTu.name != "EventActor_R103")
                Object.DestroyImmediate(s.clipTu.gameObject);
            s.clipTu = eventActor.transform;
            s.repairEventActor = eventActor.transform;
            s.repairEventMotion = AssetDatabase.LoadAllAssetsAtPath(A + "RepairEventActor.fbx").OfType<AnimationClip>().First(c => !c.name.StartsWith("__preview__"));
            var bones = eventActor.GetComponentsInChildren<Transform>(true);
            var handL = bones.Single(t => t.name == "handL");
            var handR = bones.Single(t => t.name == "handR");
            Part("EVIDENCE", "RepairTool", "Tool_in_hand", handL, Vector3.zero);
            var bind = eventActor.AddComponent<RepairHandBinding>();
            bind.rightHand = handR;
            bind.repairAttachment = s.clipRepair.GetComponentsInChildren<Transform>(true).Single(t => t.name == "foreR");
            var stringGo = new GameObject("R12_repair_string");
            stringGo.transform.SetParent(eventActor.transform, false);
            bind.repairString = stringGo.AddComponent<LineRenderer>();
            bind.repairString.startWidth = bind.repairString.endWidth = .007f;
            bind.repairString.material = AssetDatabase.LoadAssetAtPath<Material>(A + "Materials/Paper ivory.mat");
            if (!s.clipRepair.Find("Readable_R12_tag"))
                Part("EVIDENCE", "Label_R12", "Readable_R12_tag", s.clipRepair, Vector3.zero);
            s.clipCamera.transform.localPosition = new Vector3(2.7f, 4.7f, -1f);
            s.clipCamera.transform.LookAt(clipRoot.TransformPoint(new Vector3(.8f, 4.1f, 1.55f)));
            s.clipCamera.fieldOfView = 30;
            s.clipCamera.enabled = false;
            Layer(clipRoot, 30);
            var brass = new Material(Shader.Find("Universal Render Pipeline/Lit"));
            brass.color = new Color(.74f, .53f, .13f);
            string brassPath = A + "Materials/LatchReadability.mat";
            if (!AssetDatabase.LoadAssetAtPath<Material>(brassPath))
                AssetDatabase.CreateAsset(brass, brassPath);
            else
                Object.DestroyImmediate(brass);
            brass = AssetDatabase.LoadAssetAtPath<Material>(brassPath);
            foreach (var gate in s.GetComponentsInChildren<ReturnGateMechanism>(true))
            {
                gate.latch.localPosition = new Vector3(1.51f, .92f, 0);
                gate.latch.GetComponent<Renderer>().sharedMaterial = brass;
                if (gate.rope)
                    gate.rope.GetComponent<Renderer>().enabled = false;
                gate.Apply();
            }

            var stage = s.modelGate.transform.parent;
            if (!stage.Find("DK_visible_handle"))
            {
                var handle = Part("MECHANISM", "Handle_DK", "DK_visible_handle", stage, new Vector3(1.54f, 1.2f, -4.5f));
                s.modelGate.handle = handle.transform;
                var hook = Part("MECHANISM", "Hook_M", "M_visible_hook", stage, new Vector3(1.54f, 1.2f, -4.5f));
                hook.SetActive(false);
            }

            var hands = s.modelTu.GetComponent<PresentationHands>();
            if (!hands)
                hands = s.modelTu.gameObject.AddComponent<PresentationHands>();
            hands.session = s;
            hands.actor = s.modelTu.GetComponent<InvestigationActor>();
            hands.handL = s.modelTu.GetComponentsInChildren<Transform>(true).Single(t => t.name == "handL");
            hands.handR = s.modelTu.GetComponentsInChildren<Transform>(true).Single(t => t.name == "handR");
            var operatorHands = s.modelKhai.GetComponent<PresentationHands>();
            if (!operatorHands)
                operatorHands = s.modelKhai.gameObject.AddComponent<PresentationHands>();
            operatorHands.session = s;
            operatorHands.actor = s.modelKhai.GetComponent<InvestigationActor>();
            operatorHands.operatorAtHandle = true;
            operatorHands.handR = s.modelKhai.GetComponentsInChildren<Transform>(true).Single(t => t.name == "handR");
            if (!stage.Find("Control_post"))
                Part("MECHANISM", "ControlPost_DK", "Control_post", stage, new Vector3(1.54f, 0, -4.5f));
            if (s.gate.handle)
                s.gate.handle.SetParent(s.gate.transform, true);
            var mainHook = workshop.Find("M_hook_dust");
            if (mainHook)
            {
                mainHook.localPosition = new Vector3(1.54f, 1.2f, -4.5f);
                mainHook.SetParent(s.gate.transform, true);
            }

            if (!s.gate.transform.Find("Control_post"))
            {
                var post = Part("MECHANISM", "ControlPost_DK", "Control_post", s.gate.transform, new Vector3(1.54f, -3, -6));
                post.AddComponent<BoxCollider>();
            }

            if (!s.modelGate.wedgeVisual)
                s.modelGate.wedgeVisual = Part("MECHANISM", "Wedge", "Visible_wedge", s.modelGate.transform, Vector3.zero);
            s.modelGate.wedgeVisual.transform.localPosition = new Vector3(1.18f, .08f, -.83f);
            s.modelGate.wedgeVisual.SetActive(false);
            Layer(stage, 29);
            s.diagnostics = false;
            s.repairEventMotion.SampleAnimation(eventActor, 0);
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            AssetDatabase.SaveAssets();
            var log = new StringBuilder("R103 source assets integrated. r102 untouched.\n");
            log.AppendLine("Event clip=" + s.repairEventMotion.name + " length=" + s.repairEventMotion.length);
            log.AppendLine("Interactions=" + s.GetComponentsInChildren<InvestigationInteractable>(true).Length);
            log.AppendLine("Namespace=" + s.data.namespaceId + " diagnostics=" + s.diagnostics);
            File.WriteAllText("Test/KetQua/investigation_r103/integration.txt", log.ToString());
            r.Log(log.ToString());
        }
    }
}

